window.TESTS_OFICIALES = (window.TESTS_OFICIALES || []).concat([
  { id: "dgt-279", numero: 279, fecha: "2026-10", etiqueta: "Octubre 2026", url: "https://revista.dgt.es/es/test/Test-num-279.shtml",
    preguntas: [
      { id: "dgt279-01", tema: "maniobras", pregunta: "Si no es posible dejar el vehículo paralelo al borde de la calzada, ¿se puede parar o estacionar en otra posición?", opciones: ["Sí, si la vía o las circunstancias lo aconsejan.", "Solo si hay una señal que permita aparcar en batería.", "No, en ningún caso."], correcta: 0, explicacion: "Si la vía o las circunstancias lo aconsejan, se puede parar o estacionar en otra posición. No hace falta una señal especial para ello." },
      { id: "dgt279-02", tema: "maniobras", pregunta: "¿Cómo se debe hacer un cambio de carril en una vía con mucho tráfico?", opciones: ["Usando el arcén.", "Avisando con suficiente antelación.", "Haciendo la maniobra deprisa para no estorbar."], correcta: 1, explicacion: "Hay que avisar con tiempo y comprobar que hay espacio, para que los demás puedan reaccionar. Nunca se usa el arcén para ello." },
      { id: "dgt279-03", tema: "senales", pregunta: "Esta señal de peligro, ¿de qué advierte?", opciones: ["De un estrechamiento de la calzada.", "De un tramo con circulación en los dos sentidos.", "De un tramo con prioridad frente a los vehículos que vienen de frente."], correcta: 1, explicacion: "Es una señal triangular de peligro que avisa de que más adelante los vehículos circulan en los dos sentidos por la misma calzada.", senal: {forma:"triangulo", simbolo:"⇅"} },
      { id: "dgt279-04", tema: "factores", pregunta: "Si toma un medicamento que puede afectar a la conducción, ¿qué debe hacer para reducir el riesgo de accidente?", opciones: ["Conocer sus posibles efectos secundarios y seguir las indicaciones del médico.", "Evitar conducir mientras dure el tratamiento.", "Tomar café para contrarrestar sus efectos."], correcta: 0, explicacion: "Lo prudente es conocer los efectos secundarios del medicamento y seguir las indicaciones del médico o del prospecto." },
      { id: "dgt279-05", tema: "factores", pregunta: "¿A qué se deben sobre todo las distracciones al volante?", opciones: ["Al estado psicofísico del conductor y a su comportamiento.", "A la colocación de los mandos dentro del vehículo.", "A factores externos, como la vía o su entorno."], correcta: 0, explicacion: "La mayoría de las distracciones dependen del propio conductor: cómo está física y mentalmente y cómo se comporta al volante." },
      { id: "dgt279-06", tema: "velocidad", pregunta: "Un conjunto formado por un vehículo con un remolque de 750 kg de masa máxima autorizada, ¿a qué velocidad máxima puede circular por una autovía?", opciones: ["A 100 km/h.", "A 120 km/h.", "A 90 km/h."], correcta: 2, explicacion: "Con un remolque de hasta 750 kg, el límite en autovía baja a 90 km/h, aunque un turismo sin remolque podría ir a 120 km/h." },
      { id: "dgt279-07", tema: "prioridad", pregunta: "Una ambulancia que usa solo la señal especial luminosa, sin la acústica, ¿hay que cederle el paso?", opciones: ["No, debe usar a la vez la señal luminosa y la acústica.", "Sí.", "Sí, pero solo en vías urbanas."], correcta: 1, explicacion: "Un vehículo prioritario con la señal luminosa tiene preferencia aunque no use la acústica, así que hay que cederle el paso en cualquier vía." },
      { id: "dgt279-08", tema: "via", pregunta: "Una persona que empuja a pie una bicicleta, si ir por la acera molesta a otros peatones, ¿por dónde puede circular?", opciones: ["Por la calzada, pero nunca por el arcén.", "Por el arcén, pero nunca por la calzada.", "Por el arcén o por la calzada."], correcta: 2, explicacion: "Quien camina empujando una bici se considera peatón. Si la acera no es adecuada, puede ir por el arcén o por la calzada, con precaución." },
      { id: "dgt279-09", tema: "velocidad", pregunta: "¿Es peligroso circular a una velocidad inferior a la mínima permitida, sin ninguna causa que lo justifique?", opciones: ["Sí, y además está prohibido.", "No, porque ir más despacio es siempre más seguro.", "Sí, porque lo más seguro es ir a la velocidad máxima permitida."], correcta: 0, explicacion: "Ir muy despacio sin motivo entorpece a los demás y puede causar accidentes; por eso está prohibido." },
      { id: "dgt279-10", tema: "velocidad", pregunta: "Un turismo circula a 100 km/h por una autovía. ¿Va a una velocidad adecuada?", opciones: ["No, lo aconsejable sería ir a 120 km/h.", "Sí, si lo permiten el tráfico y las condiciones de la vía.", "Sí, siempre que no moleste a los demás."], correcta: 1, explicacion: "El límite es un máximo. La velocidad adecuada depende del tráfico, de la vía y de las condiciones, y no siempre es la máxima permitida." },
      { id: "dgt279-11", tema: "seguridad", pregunta: "Una vez abrochado el cinturón de seguridad, ¿qué es lo aconsejable?", opciones: ["Ponerle una pinza para que quede más holgado.", "Comprobar que está bien colocado y ajustado al cuerpo.", "Aflojarlo a la altura del abdomen para ir más cómodo."], correcta: 1, explicacion: "El cinturón protege solo si va bien ajustado y pegado al cuerpo. Nunca debe sujetarse con pinzas ni llevarse flojo." },
      { id: "dgt279-12", tema: "maniobras", pregunta: "Un motorista realiza un adelantamiento fuera de poblado. ¿Qué separación lateral debe dejar con el vehículo adelantado?", opciones: ["Superior a 1,50 metros.", "Superior a 1,20 metros e inferior a 1,50 metros.", "La proporcional a la anchura de la vía."], correcta: 0, explicacion: "La respuesta correcta es dejar más de 1,5 metros de separación lateral con el vehículo adelantado." },
      { id: "dgt279-13", tema: "senales", pregunta: "Esta señal está a la entrada de un camino. ¿Puede circular por él un turismo?", opciones: ["No, porque es un camino reservado para animales de montura.", "Sí, con precaución, porque también pueden circular animales de montura.", "Sí, porque la señal prohíbe el paso a animales de montura."], correcta: 0, explicacion: "La señal indica que ese camino está reservado a animales de montura, así que los turismos no pueden utilizarlo.", senal: {forma:"circulo-azul", simbolo:"🐴"} },
      { id: "dgt279-14", tema: "accidentes", pregunta: "Para compensar el riesgo de conducir con lluvia, ¿qué hay que hacer?", opciones: ["Aumentar la distancia de seguridad, porque se frena peor.", "Reducir la distancia de seguridad y poner las luces de cruce para que nos vean.", "Bajar la presión de los neumáticos para ganar adherencia."], correcta: 0, explicacion: "Con el asfalto mojado el coche necesita más espacio para frenar. Ampliar la distancia de seguridad evita alcances." },
      { id: "dgt279-15", tema: "via", pregunta: "¿Cuántas plazas, como máximo, puede tener un vehículo de movilidad personal (VMP)?", opciones: ["Una plaza.", "Dos plazas.", "Una o dos, según el tipo de vehículo."], correcta: 0, explicacion: "Los vehículos de movilidad personal están pensados para una sola persona: tienen una única plaza." }
    ] },
  { id: "dgt-278", numero: 278, fecha: "2026-06", etiqueta: "Junio 2026", url: "https://revista.dgt.es/es/test/Test-num-278.shtml",
    preguntas: [
      { id: "dgt278-02", tema: "factores", pregunta: "¿Por qué afecta el consumo de cannabis a la conducción?", opciones: ["Aumenta la atención del conductor.", "Aumenta el tiempo de reacción.", "Disminuye la somnolencia."], correcta: 1, explicacion: "El cannabis altera la percepción y la coordinación y alarga la reacción: el conductor tarda más en responder ante un imprevisto." },
      { id: "dgt278-03", tema: "maniobras", pregunta: "¿Puede un turismo adelantar dentro de un túnel con un solo carril por sentido?", opciones: ["No, porque su sentido de circulación tiene un solo carril.", "Sí, si no viene ningún vehículo de frente.", "No, porque en los túneles siempre está prohibido adelantar."], correcta: 0, explicacion: "Con un solo carril por sentido no se puede adelantar dentro del túnel. No está prohibido siempre, sino según los carriles que haya." },
      { id: "dgt278-04", tema: "seguridad", pregunta: "Si tiene que circular con una rueda de repuesto temporal o de emergencia, ¿qué debe tener en cuenta?", opciones: ["Las indicaciones del fabricante de esa rueda.", "Que, si está homologada, dura lo mismo que una rueda normal.", "Que su presión debe ser mayor que la de las otras tres."], correcta: 0, explicacion: "Las ruedas temporales tienen límites de velocidad y de distancia que indica el fabricante, y hay que respetarlos." },
      { id: "dgt278-05", tema: "senales", pregunta: "¿Qué indican las marcas viales azules en la calzada?", opciones: ["Una zona donde se puede aparcar libremente, igual que con las blancas.", "Que el tiempo de estacionamiento está limitado en ciertas horas del día.", "Que aparcar está prohibido."], correcta: 1, explicacion: "Las marcas azules señalan una zona de estacionamiento regulado: se puede aparcar, pero con tiempo limitado en ciertos horarios." },
      { id: "dgt278-06", tema: "factores", pregunta: "Factores como la calidad del sueño, los sedantes o la monotonía, ¿afectan igual a todos los conductores?", opciones: ["Solo afectan a quienes conducen sobre todo de noche.", "No: el mismo factor puede afectar de forma distinta a cada persona.", "Sí, afectan igual a todos."], correcta: 1, explicacion: "Cada persona reacciona de forma distinta ante los mismos factores. Por eso hay que ser prudente aunque uno se sienta bien." },
      { id: "dgt278-07", tema: "maniobras", pregunta: "En una vía urbana, y estando en el carril más adecuado para su destino, ¿puede abandonarlo?", opciones: ["Sí, para prepararse a girar, adelantar, parar o estacionar.", "No, en ningún caso.", "Sí, pero solo para cambiar de dirección."], correcta: 0, explicacion: "Se puede cambiar de carril para prepararse a girar, adelantar, parar o estacionar, siempre avisando y sin molestar a los demás." },
      { id: "dgt278-08", tema: "alumbrado", pregunta: "En una vía urbana, ¿hay que tocar el claxon para avisar de que vamos a adelantar?", opciones: ["Sí, salvo cerca de un hospital.", "Sí, a intervalos cortos y sin sonido estridente.", "No, no hace falta."], correcta: 2, explicacion: "En poblado el claxon se reserva para casos de peligro. Para adelantar basta con mirar, señalizar y comprobar que hay espacio suficiente." },
      { id: "dgt278-09", tema: "alumbrado", pregunta: "Circula con luz de carretera y se acerca a un vehículo más lento que va en su mismo sentido. ¿Debe cambiar a luz de cruce?", opciones: ["No, no es necesario ni aconsejable.", "Sí, para no deslumbrar a través del retrovisor.", "Solo si no piensa adelantarlo."], correcta: 1, explicacion: "La luz de carretera deslumbra al conductor de delante a través del retrovisor, así que hay que pasar a la de cruce al acercarse." },
      { id: "dgt278-10", tema: "maniobras", pregunta: "Si al iniciar un adelantamiento las circunstancias dificultan terminarlo, ¿qué debe hacer el conductor?", opciones: ["Volver a su carril y avisar a los que vienen detrás.", "Que el conductor adelantado se aparte al arcén.", "Acelerar y terminar la maniobra, aunque sea arriesgado."], correcta: 0, explicacion: "Si no se puede completar la maniobra con seguridad, hay que volver al carril y avisar a los que vienen detrás. Nunca se debe forzar." },
      { id: "dgt278-11", tema: "velocidad", pregunta: "En una carretera convencional con un carril por sentido, ¿cuál es la velocidad máxima de un ciclomotor?", opciones: ["45 km/h.", "80 km/h.", "60 km/h."], correcta: 0, explicacion: "Los ciclomotores no pueden superar los 45 km/h en carretera convencional." },
      { id: "dgt278-12", tema: "prioridad", pregunta: "¿Cuál es una de las infracciones con más riesgo para los peatones?", opciones: ["No ceder el paso en un paso de peatones.", "Circular en sentido contrario por una autovía.", "No guardar la distancia de seguridad con el vehículo de delante."], correcta: 0, explicacion: "En un paso de peatones el peatón tiene prioridad. No respetarla pone en peligro directo a la persona más vulnerable de la vía." },
      { id: "dgt278-13", tema: "seguridad", pregunta: "¿Quién debe vigilar que los ocupantes del vehículo viajen en una posición adecuada para su seguridad?", opciones: ["Los pasajeros mayores de edad.", "El pasajero del asiento delantero.", "El conductor."], correcta: 2, explicacion: "El conductor es responsable de que todos los ocupantes vayan bien sentados y sujetos, también los pasajeros." },
      { id: "dgt278-14", tema: "prioridad", pregunta: "Un vehículo de la Policía de Tráfico se coloca detrás del suyo y enciende una luz roja destellante que se ve hacia delante. ¿Qué debe hacer?", opciones: ["Detenerse y seguir las instrucciones del agente, si las da.", "Reducir la velocidad y apartarse a la derecha para dejarle adelantar.", "Detenerse a la izquierda de la calzada, delante del vehículo policial."], correcta: 0, explicacion: "La luz roja destellante que se ve hacia delante indica que hay que detenerse. Después se siguen las indicaciones de los agentes." },
      { id: "dgt278-15", tema: "accidentes", pregunta: "¿Es peligroso conducir con el sol dando directamente en los ojos?", opciones: ["Sí, aunque con luz de carretera se ve mejor.", "No, porque hay más luz y se ve mejor.", "Sí, la visión se reduce y cuesta distinguir lo que ocurre alrededor."], correcta: 2, explicacion: "El deslumbramiento reduce mucho la visión. Conviene bajar la visera, usar gafas de sol y reducir la velocidad si hace falta." }
    ] },
  { id: "dgt-277", numero: 277, fecha: "2026-03", etiqueta: "Marzo 2026", url: "https://revista.dgt.es/es/test/Test-num-277.shtml",
    preguntas: [
      { id: "dgt277-01", tema: "senales", pregunta: "¿Qué indica esta señal?", opciones: ["La proximidad de un lugar donde se puede dar la vuelta al mismo nivel.", "La proximidad de un lugar donde se puede cambiar de dirección.", "La dirección que los vehículos están obligados a seguir."], correcta: 0, explicacion: "Es una señal azul cuadrada de indicación: avisa de un punto donde se puede dar la vuelta sin cambiar de nivel.", senal: {forma:"cuadrado-azul", simbolo:"↶"} },
      { id: "dgt277-02", tema: "maniobras", pregunta: "¿Puede el conductor de una motocicleta parar en un carril reservado para autobuses?", opciones: ["Sí, mientras no estorbe a los autobuses.", "No, está prohibido.", "Puede parar, pero no estacionar."], correcta: 1, explicacion: "En un carril reservado para autobuses no pueden parar ni estacionar otros vehículos, y eso incluye a las motos." },
      { id: "dgt277-03", tema: "maniobras", pregunta: "¿Puede un vehículo salir de un estacionamiento marcha atrás para incorporarse a la circulación?", opciones: ["Sí, mientras no invada un cruce.", "Sí, si el recorrido no supera los 20 metros.", "Sí, aunque el recorrido sea de más de 20 metros."], correcta: 0, explicacion: "Puede hacerlo mientras no invada un cruce ni moleste a los demás. La longitud del recorrido no es el criterio." },
      { id: "dgt277-04", tema: "velocidad", pregunta: "¿Qué determina la distancia de frenado?", opciones: ["Solo la velocidad a la que se circula.", "Varios factores: la velocidad, el estado de la vía y el del vehículo.", "Solo el estado del vehículo."], correcta: 1, explicacion: "La distancia de frenado depende de varios factores a la vez: sobre todo de la velocidad, del pavimento y del estado del vehículo." },
      { id: "dgt277-05", tema: "seguridad", pregunta: "Si hay un accidente y los ocupantes no llevan cinturón, ¿en qué plazas se multiplican casi por dos las probabilidades de morir?", opciones: ["Solo en la del conductor.", "Solo en las delanteras.", "En todas las plazas del vehículo."], correcta: 2, explicacion: "Sin cinturón, el riesgo de morir en un accidente se duplica casi en cualquier plaza. Por eso el cinturón es obligatorio para todos." },
      { id: "dgt277-06", tema: "seguridad", pregunta: "En un turismo, ¿es obligatorio llevar dos chalecos reflectantes?", opciones: ["Solo es obligatorio en motocicletas, no en turismos.", "Sí, uno por cada plaza del vehículo.", "No."], correcta: 2, explicacion: "No hace falta llevar dos, ni uno por plaza. En el turismo, la prenda de alta visibilidad forma parte del equipo y se usa al bajarse a la calzada o al arcén en vía interurbana." },
      { id: "dgt277-07", tema: "prioridad", pregunta: "Si una intersección con prioridad está saturada y el conductor prevé quedarse parado dentro de ella, ¿qué debe hacer?", opciones: ["Entrar, porque tiene prioridad de paso.", "Tocar el claxon con insistencia hasta que le dejen pasar.", "No entrar en la intersección."], correcta: 2, explicacion: "No se entra en un cruce si es probable quedarse dentro. La prioridad no sirve de nada si el cruce está bloqueado." },
      { id: "dgt277-08", tema: "senales", pregunta: "Una luz roja intermitente, o dos luces rojas alternas intermitentes en un semáforo, ¿qué significan?", opciones: ["Permiten el paso con precaución.", "Prohíben temporalmente el paso.", "Obligan a reducir la velocidad antes de pasar."], correcta: 1, explicacion: "La luz roja intermitente de un semáforo prohíbe el paso de forma temporal, así que hay que detenerse." },
      { id: "dgt277-09", tema: "factores", pregunta: "En general, ¿cómo afecta un trastorno depresivo a la conducción?", opciones: ["Se procesa mejor la información relevante, sobre todo en tráfico complejo.", "Se distrae con más facilidad y puede tener somnolencia.", "Se concentra con más facilidad."], correcta: 1, explicacion: "La depresión suele restar atención y energía, y favorece distracciones y somnolencia, lo que aumenta el riesgo al volante." },
      { id: "dgt277-10", tema: "velocidad", pregunta: "En una vía de doble sentido de circulación, ¿qué vehículos deben mantener 50 metros de separación con el de delante cuando no quieran adelantar?", opciones: ["Todos los camiones, sea cual sea su masa máxima autorizada.", "Los conjuntos de vehículos de más de 10 metros de longitud.", "Los turismos."], correcta: 1, explicacion: "Los conjuntos de vehículos de más de 10 metros, como un camión con remolque, deben guardar 50 metros con el de delante en vías de doble sentido cuando no adelantan." },
      { id: "dgt277-11", tema: "seguridad", pregunta: "En un vehículo de nueve plazas, incluida la del conductor, ¿pueden viajar nueve menores de edad?", opciones: ["No, se supera el número de plazas autorizado.", "Sí, si todos tienen menos de 12 años.", "Sí, si el conductor es su padre, madre o tutor."], correcta: 0, explicacion: "Las nueve plazas incluyen la del conductor: como máximo caben ocho pasajeros, y no se puede superar el número de plazas autorizado." },
      { id: "dgt277-12", tema: "seguridad", pregunta: "¿Qué puede verse afectado si se cambia el carenado de una motocicleta?", opciones: ["Solo la estética.", "La aerodinámica y el consumo.", "La visibilidad del vehículo."], correcta: 1, explicacion: "El carenado cambia la aerodinámica de la moto y, con ella, su consumo. No es solo una cuestión estética." },
      { id: "dgt277-13", tema: "factores", pregunta: "¿Existe riesgo de accidente si se habla por manos libres mientras se conduce?", opciones: ["No, el dispositivo evita cualquier riesgo.", "Solo si la conversación dura más de cinco minutos.", "Sí, hay cierto riesgo porque disminuye la atención."], correcta: 2, explicacion: "Aunque sea manos libres, la conversación reparte la atención y retrasa los reflejos. Por eso sí hay riesgo." },
      { id: "dgt277-14", tema: "accidentes", pregunta: "¿Qué factor de riesgo provoca más accidentes de tráfico?", opciones: ["El factor humano.", "El factor vía y su entorno.", "El factor vehículo."], correcta: 0, explicacion: "La mayoría de los accidentes tienen un componente humano, como distracciones, velocidad o alcohol. Por eso es el factor principal." },
      { id: "dgt277-15", tema: "via", pregunta: "¿Cómo se llama, como norma general, el tramo de carretera que atraviesa un poblado?", opciones: ["Carretera convencional.", "Travesía.", "Autovía."], correcta: 1, explicacion: "Se llama travesía al tramo de carretera que discurre por poblado. Tiene sus propias normas, como el límite de velocidad." }
    ] },
  { id: "dgt-276", numero: 276, fecha: "2025-12", etiqueta: "Diciembre 2025", url: "https://revista.dgt.es/es/test/Test-num-276.shtml",
    preguntas: [
      { id: "dgt276-01", tema: "seguridad", pregunta: "¿Puede circular un turismo si tiene roto el retrovisor exterior izquierdo?", opciones: ["Sí, porque el retrovisor exterior izquierdo no es obligatorio.", "Solo si lleva retrovisor interior.", "No, si el conductor no puede ver lo que viene por detrás."], correcta: 2, explicacion: "Lo que importa es poder ver la circulación de detrás. Si el retrovisor roto impide esa visión, no se puede circular." },
      { id: "dgt276-02", tema: "factores", pregunta: "¿Qué es un microsueño?", opciones: ["Un sueño de unos segundos en el que se sueña mientras se conduce.", "Un periodo de unos segundos en el que el conductor se queda ligeramente dormido sin darse cuenta.", "Un descanso corto que el conductor se toma cuando se siente cansado."], correcta: 1, explicacion: "Es un sueño de unos segundos que la persona no percibe. Es muy peligroso al volante porque el vehículo queda sin control durante ese tiempo." },
      { id: "dgt276-03", tema: "factores", pregunta: "En una retención con los vehículos parados, ¿se puede usar el teléfono móvil?", opciones: ["No, salvo en vías urbanas.", "Solo con dispositivo de manos libres y sin auriculares.", "Sí, porque el vehículo no está en movimiento."], correcta: 1, explicacion: "Aunque el coche esté parado, el conductor sigue conduciendo. Solo se permite el manos libres, sin auriculares." },
      { id: "dgt276-04", tema: "senales", pregunta: "En un semáforo de carril, ¿qué significa una luz verde con forma de flecha que apunta hacia abajo?", opciones: ["Obliga a no salir del carril en el que está colocada.", "Libera de parar ante una luz roja circular.", "No exime de cumplir las normas generales de prioridad de paso."], correcta: 2, explicacion: "La flecha verde permite seguir por ese carril, pero no cambia las normas generales de prioridad de paso." },
      { id: "dgt276-05", tema: "alumbrado", pregunta: "Entre el atardecer y el amanecer, con niebla, ¿puede usar la luz de largo alcance?", opciones: ["Sí, procurando no deslumbrar a los demás.", "Solo en carreteras con un carril por sentido.", "No, está prohibido."], correcta: 0, explicacion: "La luz de largo alcance se puede usar si no deslumbra a otros usuarios. Con niebla, si la luz rebota y molesta, es mejor usar la de cruce." },
      { id: "dgt276-06", tema: "prioridad", pregunta: "En un paso de peatones con el semáforo averiado, ¿hay que ceder el paso a los peatones que quieran cruzar?", opciones: ["Sí, porque los peatones tienen prioridad en ese paso.", "No, porque los vehículos tienen prioridad.", "Solo si quien cruza es un grupo de escolares."], correcta: 0, explicacion: "En un paso de peatones, los peatones tienen prioridad aunque el semáforo no funcione." },
      { id: "dgt276-07", tema: "seguridad", pregunta: "Una motocicleta cuya ficha técnica indica que tiene estructura de autoprotección y cinturón de seguridad. ¿Puede su conductor circular sin casco?", opciones: ["Solo en vías urbanas.", "Sí.", "No."], correcta: 1, explicacion: "Las motos con estructura de autoprotección y cinturón de seguridad no tienen la obligación de llevar casco." },
      { id: "dgt276-08", tema: "maniobras", pregunta: "Si quiere salir de una autovía, ¿en qué momento debe entrar en el carril de deceleración?", opciones: ["Lo antes posible.", "Es indiferente, en cualquier momento mientras la línea sea discontinua.", "Lo más tarde posible."], correcta: 0, explicacion: "Hay que entrar en el carril de deceleración en cuanto se pueda, para frenar allí y no en el carril principal." },
      { id: "dgt276-09", tema: "maniobras", pregunta: "¿Está permitido estacionar en doble fila?", opciones: ["Sí, si el conductor no abandona el vehículo.", "No, en ningún caso.", "Solo si el estacionamiento dura menos de dos minutos."], correcta: 1, explicacion: "Estacionar en doble fila está prohibido: obliga a los demás a desviarse y bloquea la circulación." },
      { id: "dgt276-10", tema: "via", pregunta: "En una vía fuera de poblado sin zona peatonal ni arcén practicable, ¿puede un peatón circular por la calzada?", opciones: ["Sí, tomando las debidas precauciones.", "Solo si empuja un vehículo pequeño sin motor.", "No."], correcta: 0, explicacion: "Sin acera ni arcén, el peatón puede ir por la calzada con precaución, por el lado izquierdo para ver de frente el tráfico." },
      { id: "dgt276-11", tema: "factores", pregunta: "Por el deterioro de sus capacidades, ¿qué problema tienen muchas personas mayores como peatones?", opciones: ["Orientarse mejor, sobre todo en calles que no conocen.", "No calcular bien la velocidad a la que se acercan los vehículos.", "Que los bordillos de las aceras estén al mismo nivel que la calzada."], correcta: 1, explicacion: "Con la edad cuesta más calcular la velocidad y la distancia de los vehículos que se acercan, así que conviene cruzar con mucha precaución." },
      { id: "dgt276-12", tema: "seguridad", pregunta: "Acaba de comprar un turismo nuevo. ¿Cuándo debe pasar la primera inspección técnica (ITV)?", opciones: ["A los cuatro años desde la fecha de compra.", "A los dos años desde la matriculación.", "A los cuatro años desde la matriculación."], correcta: 2, explicacion: "La primera ITV de un turismo se pasa a los cuatro años de la primera matriculación, no desde la fecha de compra." },
      { id: "dgt276-13", tema: "via", pregunta: "Cerca de vías de uso exclusivo para ciclos, ¿qué precauciones hay que tomar?", opciones: ["Hacer señales acústicas para avisar de nuestra presencia.", "Moderar la velocidad y, si hace falta, detenerse.", "Mantener la velocidad y estar atento a la señalización vertical."], correcta: 1, explicacion: "Hay que circular despacio y estar preparado para parar, porque los ciclistas pueden aparecer en cualquier momento." },
      { id: "dgt276-14", tema: "senales", pregunta: "Esta señal está a la entrada de una vía. ¿Puede circular por ella un turismo?", opciones: ["No, porque es una vía reservada a todos los vehículos de dos ruedas.", "No, porque es una vía reservada a ciclos.", "Sí, porque es una vía permitida a todos los vehículos menos a los ciclos."], correcta: 1, explicacion: "La señal reserva la vía a los ciclos (bicicletas), así que los turismos no pueden circular por ella.", senal: {forma:"circulo-azul", simbolo:"🚲"} },
      { id: "dgt276-15", tema: "maniobras", pregunta: "Un turismo con etiqueta ambiental ECO, ¿puede circular por un carril VAO si solo va el conductor?", opciones: ["Sí, siempre que lleve el distintivo colocado en el parabrisas.", "No, salvo que los paneles de mensaje variable autoricen su acceso.", "Sí, aunque no lleve el distintivo en el parabrisas."], correcta: 1, explicacion: "Con una sola persona a bordo, la etiqueta ECO no basta: solo puede entrar si los paneles de mensaje variable lo autorizan. Estas reglas cambian, así que conviene fijarse en la señalización de cada tramo." }
    ] },
  { id: "dgt-275", numero: 275, fecha: "2025-10", etiqueta: "Octubre 2025", url: "https://revista.dgt.es/es/test/Test-num-275.shtml",
    preguntas: [
      { id: "dgt275-01", tema: "senales", pregunta: "Si hay semáforos con indicaciones distintas a derecha e izquierda de la calzada, ¿a cuál deben obedecer quienes siguen de frente?", opciones: ["Al situado a su derecha.", "Al que tengan más cerca.", "Al situado inmediatamente a su izquierda."], correcta: 2, explicacion: "Cuando hay semáforos a ambos lados con indicaciones distintas, quien sigue de frente obedece el situado a su izquierda." },
      { id: "dgt275-02", tema: "senales", pregunta: "Hay una doble línea continua en el centro de la calzada. ¿Qué indica?", opciones: ["Que la calzada es peligrosa.", "Que existe un carril especial.", "Que no se puede cruzarla ni pisarla."], correcta: 2, explicacion: "La doble línea continua central prohíbe cruzarla o pisarla." },
      { id: "dgt275-03", tema: "via", pregunta: "Al cruzar un arcén por el que circulan peatones, ¿qué debe hacer?", opciones: ["Avisarles con señales acústicas para que se aparten.", "Cederles el paso solo si van en grupo.", "Cederles el paso si no hay zona peatonal."], correcta: 2, explicacion: "Si no hay zona peatonal, el vehículo que cruza el arcén debe ceder el paso a los peatones que lo usan." },
      { id: "dgt275-05", tema: "via", pregunta: "¿Puede un furgón circular por un carril reversible?", opciones: ["Solo si su masa máxima autorizada no supera 3.500 kg.", "No.", "Sí."], correcta: 2, explicacion: "Un furgón puede usar el carril reversible cuando está abierto en su sentido: su masa no lo impide." },
      { id: "dgt275-06", tema: "maniobras", pregunta: "Como norma general, en una vía interurbana, ¿se puede parar o estacionar en la parte transitable del arcén?", opciones: ["Se puede parar, pero no estacionar.", "Están prohibidas tanto la parada como el estacionamiento.", "Están permitidas tanto la parada como el estacionamiento."], correcta: 1, explicacion: "Como norma general, el arcén transitable no sirve para parar ni estacionar. La excepción es una avería o una emergencia." },
      { id: "dgt275-07", tema: "maniobras", pregunta: "En una autopista se ha pasado la salida. ¿Puede volver atrás, marcha atrás, para tomarla?", opciones: ["No.", "Sí, si el recorrido no supera 15 metros.", "Sí, si no hay peligro para otros usuarios."], correcta: 0, explicacion: "En una autopista no se puede dar marcha atrás, ni siquiera un tramo corto: hay que seguir hasta la siguiente salida." },
      { id: "dgt275-08", tema: "seguridad", pregunta: "¿Puede circular con su turismo si el equipaje impide ver bien la vía por el retrovisor interior?", opciones: ["No, en ningún caso la carga puede reducir la visión por el retrovisor.", "Sí, si lleva dos retrovisores exteriores, uno a cada lado.", "Solo si el retrovisor derecho es gran angular y el interior es panorámico."], correcta: 1, explicacion: "Si la carga tapa el interior, el coche puede circular con retrovisores exteriores a los dos lados, que permiten ver lo que viene detrás." },
      { id: "dgt275-09", tema: "senales", pregunta: "Esta señal, ¿qué significado tiene?", opciones: ["Peligro por un paso a nivel con barreras o semibarreras.", "Peligro por un paso a nivel sin barreras, con más de una vía férrea.", "Peligro por un cruce con una línea de tranvía."], correcta: 0, explicacion: "Es una señal triangular de peligro que avisa de un paso a nivel con barreras o semibarreras, es decir, de un cruce con el tren.", senal: {forma:"triangulo", simbolo:"🚂"} },
      { id: "dgt275-10", tema: "factores", pregunta: "En general, un conductor con sueño, ¿cómo afronta el riesgo?", opciones: ["Acepta un nivel de riesgo mayor al conducir.", "Acepta un nivel de riesgo menor al conducir.", "Reacciona más deprisa ante un imprevisto."], correcta: 0, explicacion: "Con sueño se acepta más riesgo y se reacciona peor. Lo prudente es parar a descansar." },
      { id: "dgt275-11", tema: "accidentes", pregunta: "¿Cómo se conocen los colectivos con más probabilidad de verse implicados en accidentes de tráfico?", opciones: ["Grupos de riesgo o vulnerables en el tráfico.", "Víctimas de accidentes de tráfico.", "Grupos en riesgo de exclusión social."], correcta: 0, explicacion: "Son los usuarios vulnerables, como peatones, ciclistas o motoristas, que tienen menos protección y más riesgo en la vía." },
      { id: "dgt275-12", tema: "seguridad", pregunta: "¿Puede sobresalir por la parte trasera de un turismo la carga indivisible que transporta?", opciones: ["Sí, hasta un 10 % de la longitud del vehículo.", "No, la carga no puede sobresalir por detrás de un turismo.", "Sí, hasta un 15 % de la longitud del vehículo."], correcta: 2, explicacion: "La carga indivisible puede sobresalir por detrás hasta un 15 % de la longitud del vehículo, con la señalización que exige la norma." },
      { id: "dgt275-14", tema: "velocidad", pregunta: "Si queda detenido en un atasco, ¿qué distancia es aconsejable mantener con el vehículo de delante?", opciones: ["Un metro como máximo.", "El mínimo posible, para ocupar menos espacio.", "Dos o tres metros."], correcta: 2, explicacion: "Dejar dos o tres metros da margen para que, si nos alcanzan por detrás, no empujemos nuestro coche contra el de delante." },
      { id: "dgt275-15", tema: "seguridad", pregunta: "¿Qué condiciones deben cumplir los neumáticos de una motocicleta?", opciones: ["Las dos ruedas deben ser del mismo tamaño y características.", "La profundidad mínima del dibujo debe ser de 1,6 milímetros.", "No pueden tener bultos, deformaciones anormales ni roturas."], correcta: 2, explicacion: "Un neumático con bultos, deformaciones o roturas puede reventar en marcha, por eso no puede circular así." }
    ] },
  { id: "dgt-274", numero: 274, fecha: "2025-06", etiqueta: "Junio 2025", url: "https://revista.dgt.es/es/test/Test-num-274.shtml",
    preguntas: [
      { id: "dgt274-01", tema: "alumbrado", pregunta: "De día, ¿cuándo es obligatorio encender el alumbrado?", opciones: ["En un puente móvil.", "En un carril reservado a vehículos de alta ocupación (VAO).", "En pasos inferiores o tramos afectados por la señal de túnel."], correcta: 2, explicacion: "De día también hay que encender las luces en pasos inferiores y en tramos señalizados como túnel, donde la luz natural es escasa." },
      { id: "dgt274-02", tema: "senales", pregunta: "¿Cuál es el orden de prioridad entre tipos de señales?", opciones: ["Señales verticales, agentes y semáforos.", "Agentes, semáforos y señales verticales.", "Semáforos, agentes y señales verticales."], correcta: 1, explicacion: "Mandan primero las órdenes de los agentes, después los semáforos y por último las señales verticales." },
      { id: "dgt274-03", tema: "senales", pregunta: "¿A qué vehículos prohíbe la entrada esta señal?", opciones: ["A ciclos y ciclomotores.", "Solo a ciclos.", "A todos los vehículos de dos ruedas."], correcta: 1, explicacion: "La señal prohíbe la entrada a las bicicletas (ciclos). No prohíbe a los ciclomotores ni a las motos.", senal: {forma:"circulo-rojo", simbolo:"🚲"} },
      { id: "dgt274-04", tema: "factores", pregunta: "En general, ¿cómo es el conductor bajo los efectos de la cocaína?", opciones: ["Inseguro, e infravalora sus capacidades.", "Se concentra mejor, así que sus decisiones son más seguras.", "Competitivo e impulsivo."], correcta: 2, explicacion: "La cocaína da una falsa sensación de energía y seguridad: el conductor se vuelve impulsivo y se arriesga más." },
      { id: "dgt274-05", tema: "seguridad", pregunta: "¿Están las embarazadas obligadas a usar el cinturón de seguridad?", opciones: ["Sí, como norma general.", "No, porque es peligroso para el feto.", "Solo si el cinturón les dificulta moverse para conducir."], correcta: 0, explicacion: "Sí, el cinturón es obligatorio también para ellas, y protege tanto a la madre como al bebé." },
      { id: "dgt274-06", tema: "factores", pregunta: "El calor afecta a la conducción. ¿Cómo suele reaccionar un conductor afectado por el calor?", opciones: ["Tarda más en reaccionar y es menos agresivo.", "Tarda más en reaccionar y es más agresivo.", "Tarda menos en reaccionar y es más agresivo."], correcta: 1, explicacion: "Con calor se reacciona más despacio y aumenta la irritabilidad, así que hay que extremar la prudencia." },
      { id: "dgt274-07", tema: "maniobras", pregunta: "Si la luz de marcha atrás está averiada, ¿cómo se indica que se va a dar marcha atrás?", opciones: ["Moviendo el brazo de arriba abajo.", "Con el brazo extendido y la palma de la mano hacia atrás.", "Avisando con el claxon."], correcta: 1, explicacion: "Con la luz averiada se avisa con el brazo extendido hacia atrás, de forma que los demás lo vean." },
      { id: "dgt274-08", tema: "maniobras", pregunta: "En una vía interurbana con un carril por sentido y sin carril específico, ¿dónde debe situarse un ciclomotor para girar a la izquierda?", opciones: ["En el eje de la calzada, sin invadir el carril contrario.", "En la parte central de su carril.", "A la derecha, fuera de la calzada, siempre que sea posible."], correcta: 2, explicacion: "Se indica que, cuando es posible, el ciclomotor se coloque a la derecha y fuera de la calzada para girar, sin invadir el sentido contrario." },
      { id: "dgt274-09", tema: "senales", pregunta: "Ante una marca vial transversal discontinua de ceda el paso, ¿hay que detenerse antes de cruzarla?", opciones: ["Solo si hay poca visibilidad.", "No, porque no detenerse no supone ningún peligro.", "No, salvo que sea necesario para ceder el paso."], correcta: 2, explicacion: "La marca de ceda el paso obliga a ceder, pero no siempre a parar: solo hay que detenerse si hace falta para dejar pasar a quien tiene prioridad." },
      { id: "dgt274-10", tema: "factores", pregunta: "Para evitar la somnolencia al volante, ¿cuántas horas es recomendable dormir?", opciones: ["Entre 5 y 7 horas al día.", "Menos de las necesarias, para mantener alto el nivel de alerta.", "Las horas suficientes para descansar, que para la mayoría son entre 7 y 9."], correcta: 2, explicacion: "Lo recomendable es dormir lo suficiente para ir descansado, que para la mayoría de personas son entre 7 y 9 horas." },
      { id: "dgt274-11", tema: "accidentes", pregunta: "Para evitar accidentes con motos y ciclomotores, sobre todo en ciudad, ¿cómo debe comportarse el conductor de un turismo?", opciones: ["Circular en paralelo y lo más cerca posible de los vehículos de dos ruedas.", "Mirar con frecuencia por los retrovisores.", "Reducir o incluso eliminar la distancia de seguridad."], correcta: 1, explicacion: "Las motos son fáciles de pasar por alto. Mirar a menudo por los retrovisores ayuda a detectarlas a tiempo." },
      { id: "dgt274-12", tema: "via", pregunta: "En un carril habilitado en sentido contrario por obras en la calzada, ¿qué vehículos pueden usarlo?", opciones: ["Todos los que estén autorizados a circular por esa vía.", "Solo turismos y motocicletas.", "Turismos de hasta 3.500 kg de MMA y motocicletas."], correcta: 0, explicacion: "Un carril provisional de obras está abierto a todos los vehículos autorizados a circular por esa vía, mientras la señalización lo permita." },
      { id: "dgt274-13", tema: "maniobras", pregunta: "En vías con un carril por sentido, ¿se puede ocupar el carril contrario para adelantar a un ciclista?", opciones: ["Sí, siempre que pueda hacerse con seguridad.", "No.", "Solo si ambos sentidos están separados por una línea blanca discontinua."], correcta: 0, explicacion: "Se puede si la maniobra es segura y no compromete a quienes vienen de frente, dejando al menos 1,5 metros al ciclista." },
      { id: "dgt274-14", tema: "factores", pregunta: "Cuando la policía de tráfico lo requiera, ¿están los conductores obligados a someterse a la prueba de alcoholemia?", opciones: ["No; pueden negarse y seguir circulando.", "Solo en caso de accidente de tráfico.", "Sí; negarse a hacerla es un delito del Código Penal."], correcta: 2, explicacion: "Sí, están obligados, y negarse a hacer la prueba cuando lo pide la autoridad es un delito." },
      { id: "dgt274-15", tema: "seguridad", pregunta: "¿Es conveniente usar un aceite de viscosidad tan baja que se vuelva muy líquido al calentarse el motor?", opciones: ["No; ese aceite no engrasa bien las piezas del motor.", "Sí; cuanto más líquido, mejor engrasa y arrastra los residuos.", "Solo si el motor se calienta demasiado, porque así engrasa mejor y baja su temperatura."], correcta: 0, explicacion: "Un aceite que se vuelve demasiado líquido con el calor deja de proteger bien el motor. Hay que usar el que recomienda el fabricante." }
    ] },
  { id: "dgt-273", numero: 273, fecha: "2025-04", etiqueta: "Abril 2025", url: "https://revista.dgt.es/es/test/Test-num-273.shtml",
    preguntas: [
      { id: "dgt273-01", tema: "seguridad", pregunta: "Un vehículo tiene las placas tapadas u obstruidas. ¿Puede circular si las placas no se leen bien?", opciones: ["No; el conductor debe asegurarse de que se lean correctamente.", "Sí, si la placa delantera se lee bien.", "Sí, si solo circula por vías urbanas y travesías."], correcta: 0, explicacion: "Las matrículas deben ser visibles y legibles en todo momento. Si no se leen, no se puede circular." },
      { id: "dgt273-02", tema: "seguridad", pregunta: "Como norma general, ¿qué debe hacer el ocupante de un turismo que no es el conductor respecto al cinturón?", opciones: ["Llevarlo puesto sin abrochar, salvo en la plaza delantera.", "Llevarlo abrochado solo en vías interurbanas.", "Llevarlo puesto y bien abrochado."], correcta: 2, explicacion: "Todos los ocupantes deben llevar el cinturón puesto y abrochado, en cualquier plaza y en cualquier vía." },
      { id: "dgt273-03", tema: "maniobras", pregunta: "Un turismo con remolque circula por una vía interurbana de tres carriles por sentido. ¿Puede usar el carril izquierdo?", opciones: ["Sí, si el conjunto no mide más de 7 metros.", "Sí, pero solo para adelantar.", "No, en ningún caso."], correcta: 0, explicacion: "Mientras el conjunto no supere los 7 metros de longitud, puede circular por el carril izquierdo." },
      { id: "dgt273-05", tema: "maniobras", pregunta: "Al adelantar a vehículos de tracción animal fuera de poblado, ¿qué separación lateral hay que guardar?", opciones: ["No inferior a 1,5 metros.", "Inferior a 1,5 metros en todos los casos.", "Siempre proporcional a la anchura y características de la vía."], correcta: 0, explicacion: "Fuera de poblado hay que dejar al menos 1,5 metros de separación lateral al adelantar a vehículos de tracción animal." },
      { id: "dgt273-06", tema: "alumbrado", pregunta: "Un vehículo queda parado en el arcén de una travesía mal iluminada, entre el atardecer y el amanecer. ¿Qué alumbrado debe dejar encendido, como norma general?", opciones: ["Ninguno.", "Las luces de emergencia.", "Las luces de posición."], correcta: 2, explicacion: "Un vehículo parado de noche en una vía mal iluminada debe mantener encendidas las luces de posición para que se vea." },
      { id: "dgt273-07", tema: "senales", pregunta: "Esta señal de peligro, ¿de qué advierte?", opciones: ["De un escalón lateral o desnivel a lo largo de un tramo.", "De pavimento deslizante por hielo o nieve.", "De una zona de calzada con pavimento muy deslizante."], correcta: 2, explicacion: "Es una señal triangular de peligro que avisa de un tramo con pavimento muy deslizante: hay que extremar la precaución y reducir la velocidad.", senal: {forma:"triangulo", simbolo:"🚗"} },
      { id: "dgt273-09", tema: "factores", pregunta: "¿Qué alteración del comportamiento provoca el alcohol con más frecuencia?", opciones: ["Respuestas impulsivas y agresivas hacia otros conductores.", "Un menor tiempo de reacción.", "Mayor facilidad para percibir semáforos y señales."], correcta: 0, explicacion: "El alcohol altera la conducta: el conductor puede reaccionar de forma impulsiva o agresiva y pierde capacidad para valorar los riesgos." },
      { id: "dgt273-11", tema: "factores", pregunta: "Si ha dormido mal o poco, ¿qué debe tener en cuenta antes de conducir?", opciones: ["Conducir por autovía durante horas impide que aparezca el sueño.", "No está en perfectas condiciones para conducir.", "Una taza de café elimina la fatiga."], correcta: 1, explicacion: "Dormir poco reduce la atención y los reflejos. El café solo disimula el cansancio y no sustituye al descanso." },
      { id: "dgt273-12", tema: "accidentes", pregunta: "Muchos accidentes graves de jóvenes se relacionan con dos factores. ¿Cuáles son?", opciones: ["Consumo de alcohol y drogas, y actitud prudente al volante.", "Falta de experiencia al volante, y consumo de alcohol y drogas.", "Velocidad excesiva, y buena percepción del riesgo."], correcta: 1, explicacion: "Los conductores jóvenes tienen poca experiencia y, a menudo, consumen alcohol o drogas. Esa combinación se relaciona con muchos accidentes graves." },
      { id: "dgt273-13", tema: "accidentes", pregunta: "¿Qué circunstancia aumenta el consumo de combustible?", opciones: ["Circular con las ventanillas subidas.", "Circular con el vehículo muy cargado.", "Circular con neumáticos sin dibujo."], correcta: 1, explicacion: "Cuanto más peso lleva el vehículo, más energía necesita para moverse y más combustible consume." },
      { id: "dgt273-14", tema: "seguridad", pregunta: "¿Qué razón explica que el vehículo sea un factor de riesgo en menor grado como causa de accidentes?", opciones: ["Las mejoras técnicas importantes en su diseño y construcción.", "Que la edad media de los vehículos es cada vez mayor.", "Que en los últimos 20 años los kilómetros recorridos han bajado cada año."], correcta: 0, explicacion: "Los coches actuales llevan muchas ayudas de seguridad, como frenos avanzados, airbags y control de estabilidad, que reducen los accidentes." },
      { id: "dgt273-15", tema: "seguridad", pregunta: "¿Qué elementos deben revisarse periódicamente y con más frecuencia que el resto?", opciones: ["Neumáticos, sistema de frenado y amortiguadores.", "Luces, batería y llantas.", "Filtro de aire, dirección y retrovisores."], correcta: 0, explicacion: "Neumáticos, frenos y amortiguadores influyen directamente en la distancia de frenado y en el control del vehículo, por eso se revisan con más frecuencia." }
    ] },
  { id: "dgt-272", numero: 272, fecha: "2024-12", etiqueta: "Diciembre 2024", url: "https://revista.dgt.es/es/test/Test-num-272.shtml",
    preguntas: [
      { id: "dgt272-01", tema: "maniobras", pregunta: "En una calzada de sentido único, ¿dónde hay que colocarse para girar a la izquierda?", opciones: ["Junto al borde izquierdo de la calzada.", "Junto al borde derecho.", "No se puede cambiar de dirección."], correcta: 0, explicacion: "En una calzada de un solo sentido, para girar a la izquierda hay que colocarse junto al borde izquierdo, y para girar a la derecha, junto al derecho." },
      { id: "dgt272-02", tema: "maniobras", pregunta: "¿Está permitido parar en una autovía o autopista?", opciones: ["Sí, en la mediana o en el arcén, indistintamente.", "Solo si el arcén es transitable y mide más de 1,5 metros.", "No, salvo en zonas habilitadas."], correcta: 2, explicacion: "En autovías y autopistas solo se para en zonas habilitadas o por avería o emergencia. El arcén no es un lugar para parar por gusto." },
      { id: "dgt272-03", tema: "prioridad", pregunta: "¿Debe entrar en un cruce si el tráfico está tan saturado que podría bloquear la circulación transversal?", opciones: ["Solo si conduce un vehículo de servicio público.", "Sí, si tiene prioridad de paso.", "No, aunque tenga prioridad."], correcta: 2, explicacion: "No hay que entrar en un cruce si es probable quedarse dentro bloqueando la circulación, aunque se tenga prioridad." },
      { id: "dgt272-04", tema: "factores", pregunta: "Si el conductor no supera la tasa máxima de alcohol, ¿puede el agente hacerle una segunda prueba?", opciones: ["No, en ningún caso.", "Sí, si muestra signos evidentes de haber bebido.", "Solo si ha estado implicado en un accidente."], correcta: 1, explicacion: "Puede hacerse una segunda prueba si el agente aprecia signos claros de consumo de alcohol, aunque la primera salga por debajo del límite." },
      { id: "dgt272-05", tema: "accidentes", pregunta: "Si empieza a llover con intensidad mientras conduce una moto, ¿qué debe hacer?", opciones: ["Moderar la velocidad e, incluso, detenerse si hace falta.", "Circular pegado a los vehículos pesados.", "Aumentar la velocidad."], correcta: 0, explicacion: "Con lluvia intensa la adherencia baja y se ve peor: hay que reducir la velocidad y parar si la visibilidad es muy mala." },
      { id: "dgt272-07", tema: "velocidad", pregunta: "Entre los efectos negativos de la velocidad está el efecto túnel. ¿Qué le ocurre al conductor?", opciones: ["Solo percibe el centro de la calzada y deja de ver los laterales.", "Tiene la falsa sensación de ir a poca velocidad.", "Percibe mejor los laterales que el centro."], correcta: 0, explicacion: "A más velocidad, el campo visual se estrecha: el conductor deja de percibir lo que ocurre a los lados." },
      { id: "dgt272-08", tema: "seguridad", pregunta: "¿Cómo debe colocarse un navegador GPS portátil?", opciones: ["Debajo del volante, lo más cerca posible del suelo.", "Justo detrás del volante, a la altura de los ojos.", "Donde no estorbe la visión ni el despliegue del airbag."], correcta: 2, explicacion: "El GPS no puede tapar la vista de la carretera ni interferir con el airbag en caso de choque." },
      { id: "dgt272-09", tema: "factores", pregunta: "¿Cuál es una de las principales causas de accidentes de las personas mayores?", opciones: ["El deterioro de las capacidades psicomotoras.", "El aumento de la visión periférica.", "Una mejor percepción y análisis de los riesgos."], correcta: 0, explicacion: "Con la edad pueden disminuir los reflejos, la vista y la coordinación, lo que aumenta el riesgo al conducir." },
      { id: "dgt272-10", tema: "accidentes", pregunta: "¿Está obligado todo conductor implicado en un accidente a detenerse para aclarar lo ocurrido?", opciones: ["Solo si es el culpable.", "Sí, pero sin crear un nuevo peligro para la circulación.", "No."], correcta: 1, explicacion: "Todo implicado debe detenerse, pero sin generar nuevos peligros para el resto de usuarios." },
      { id: "dgt272-11", tema: "seguridad", pregunta: "Si circula con la presión de los neumáticos descompensada, ¿aumenta el riesgo de perder el control?", opciones: ["Sí: la frenada es irregular y baja la estabilidad.", "No; mejora la adherencia, sobre todo en suelo mojado.", "No; aumenta el área de contacto y facilita la rodadura."], correcta: 0, explicacion: "Con presiones desiguales el vehículo frena de forma irregular y pierde estabilidad, lo que puede llevar a perder el control." },
      { id: "dgt272-12", tema: "seguridad", pregunta: "Con un pasajero en la moto, ¿qué ocurre al frenar?", opciones: ["Es más difícil que se bloquee la rueda trasera.", "El peso se desplaza hacia la parte trasera de la moto.", "Conviene soltar el acelerador y frenar solo con el freno trasero."], correcta: 0, explicacion: "Con pasajero, la rueda trasera lleva más peso y es más difícil que se bloquee al frenar." },
      { id: "dgt272-13", tema: "senales", pregunta: "Esta señal, ¿qué indica?", opciones: ["Vía reservada a ciclomotores.", "Vía reservada a ciclos.", "Prohibición de entrada a ciclomotores."], correcta: 0, explicacion: "La señal reserva esa vía a los ciclomotores: quedan excluidos los demás vehículos, incluidas las bicicletas.", senal: {forma:"circulo-azul", simbolo:"🛵"} },
      { id: "dgt272-14", tema: "accidentes", pregunta: "Si la lluvia hace el pavimento deslizante, ¿qué precauciones hay que tomar?", opciones: ["Moderar la velocidad y, si hace falta, detenerse.", "Mantener la velocidad y atender a la señalización vertical.", "Ninguna, porque las circunstancias son iguales para todos."], correcta: 0, explicacion: "Con el suelo mojado hay que reducir la velocidad y dejar más distancia. Si el riesgo es alto, lo prudente es parar." },
      { id: "dgt272-15", tema: "accidentes", pregunta: "¿Cuál de los tres factores de riesgo está menos implicado en los accidentes?", opciones: ["El factor vía y su entorno.", "El factor humano.", "El factor vehículo."], correcta: 2, explicacion: "El vehículo es el factor que menos influye en los accidentes; el factor humano es el que más." }
    ] },
  { id: "dgt-271", numero: 271, fecha: "2024-10", etiqueta: "Octubre 2024", url: "https://revista.dgt.es/es/test/Test-num-271.shtml",
    preguntas: [
      { id: "dgt271-01", tema: "maniobras", pregunta: "Un conductor que señaliza un cambio de carril, ¿tiene preferencia frente a los que circulan por el carril al que quiere pasar?", opciones: ["Sí.", "No.", "Solo si va a adelantar a un vehículo de grandes dimensiones."], correcta: 1, explicacion: "Poner el intermitente avisa a los demás, pero no da preferencia: quien ya circula por el carril de destino tiene prioridad sobre el que cambia." },
      { id: "dgt271-02", tema: "alumbrado", pregunta: "Un vehículo queda inmovilizado dentro de un paso inferior por una emergencia. ¿Qué debe hacer el conductor?", opciones: ["Permanecer dentro del vehículo.", "Parar lo más cerca posible del borde izquierdo de la calzada.", "Pedir auxilio desde el poste de socorro más próximo, si lo hay."], correcta: 2, explicacion: "En los túneles y pasos inferiores hay postes de socorro para avisar. Si existen, hay que usarlos para pedir ayuda." },
      { id: "dgt271-04", tema: "velocidad", pregunta: "Conducir durante mucho tiempo a velocidad elevada, ¿qué efecto tiene?", opciones: ["Disminuye la fatiga, pero aumenta la agresividad.", "Acelera la fatiga y, por tanto, disminuye la agresividad.", "Acelera la fatiga y hace que aumente la agresividad."], correcta: 2, explicacion: "Ir rápido durante mucho tiempo cansa antes y vuelve al conductor más agresivo, lo que aumenta el riesgo." },
      { id: "dgt271-05", tema: "factores", pregunta: "Los efectos secundarios de un medicamento, ¿pueden ser distintos en cada persona según su edad, su fatiga o su estado físico?", opciones: ["No, son iguales para todas las personas.", "Sí, pueden variar de una persona a otra.", "Solo si no se siguen los consejos del médico."], correcta: 1, explicacion: "Cada persona reacciona de forma distinta a un medicamento. Por eso hay que leer el prospecto y consultar al médico." },
      { id: "dgt271-06", tema: "factores", pregunta: "Si lleva instalado un navegador GPS, ¿qué hay que tener en cuenta?", opciones: ["Que mientras se conduce no conviene apartar la vista del navegador.", "Que las indicaciones del navegador prevalecen sobre la señalización de la vía.", "Que el criterio del conductor debe prevalecer sobre lo que indique el navegador."], correcta: 2, explicacion: "El GPS es solo una ayuda. El conductor debe seguir su propio criterio y la señalización real de la vía." },
      { id: "dgt271-07", tema: "seguridad", pregunta: "¿Cuándo hay que desactivar el airbag del asiento del copiloto?", opciones: ["Si viaja una mujer embarazada.", "Si se instala un dispositivo de retención infantil orientado hacia atrás.", "Si se instala un dispositivo de retención infantil orientado hacia delante."], correcta: 1, explicacion: "Con una silla orientada hacia atrás en el asiento del copiloto hay que desactivar el airbag, porque su impacto puede dañar al bebé." },
      { id: "dgt271-08", tema: "velocidad", pregunta: "En una autopista que atraviesa una zona urbana y no tiene señales de velocidad, ¿a qué velocidad máxima puede circular un turismo?", opciones: ["A 80 km/h.", "A 120 km/h.", "A 100 km/h."], correcta: 0, explicacion: "Dentro de poblado, sin señal específica, el límite general de autopistas y autovías es de 80 km/h." },
      { id: "dgt271-09", tema: "velocidad", pregunta: "Ante una señal de límite de velocidad, ¿se puede superar la velocidad máxima que indica?", opciones: ["Sí, en 20 km/h para adelantar.", "No.", "Sí, si lo permiten las circunstancias."], correcta: 1, explicacion: "La velocidad máxima que indica una señal es un límite obligatorio: no se puede superar." },
      { id: "dgt271-10", tema: "alumbrado", pregunta: "Con lluvia intensa en una vía interurbana no se distingue un vehículo negro a 50 metros. ¿Se puede circular con las luces de largo alcance encendidas?", opciones: ["No, está prohibido.", "Sí, porque la vía está insuficientemente iluminada.", "Solo se pueden encender la de cruce y la antiniebla delantera."], correcta: 1, explicacion: "Si la vía está insuficientemente iluminada y no se ve bien, se puede usar la luz de carretera sin deslumbrar a los demás." },
      { id: "dgt271-11", tema: "seguridad", pregunta: "La parte exterior de uno de los neumáticos tiene un bulto. ¿Es recomendable cambiarlo cuanto antes?", opciones: ["Sí, porque aumenta el riesgo de reventón.", "No, se puede seguir circulando sin riesgo importante.", "No hace falta, porque siempre se puede reparar en un taller."], correcta: 0, explicacion: "Un bulto indica un daño interno en el neumático que puede hacerlo reventar en marcha. Hay que sustituirlo cuanto antes." },
      { id: "dgt271-12", tema: "senales", pregunta: "Un agente balancea una luz amarilla. ¿Qué indica?", opciones: ["Precaución al circular.", "El carril por el que debe circular.", "Que los conductores a los que va dirigida deben detenerse."], correcta: 2, explicacion: "La luz amarilla balanceada por el agente ordena detenerse a los conductores a los que va dirigida." },
      { id: "dgt271-13", tema: "senales", pregunta: "¿Con qué marcas viales se delimitan los carriles reversibles?", opciones: ["Discontinuas, con una separación bastante más corta.", "Discontinuas simples a ambos lados.", "Dobles discontinuas a ambos lados."], correcta: 2, explicacion: "Los carriles reversibles se delimitan con dobles líneas discontinuas a ambos lados, para distinguirlos de los carriles normales." },
      { id: "dgt271-14", tema: "accidentes", pregunta: "En los periodos vacacionales y los fines de semana, ¿cómo varía el número de accidentes con víctimas mortales?", opciones: ["No varía de forma importante.", "Aumenta.", "Disminuye."], correcta: 1, explicacion: "En vacaciones y fines de semana aumentan los desplazamientos y también los accidentes mortales, por lo que hay que extremar la prudencia." },
      { id: "dgt271-15", tema: "seguridad", pregunta: "Si el turismo ha pasado la primera ITV con resultado favorable, ¿cuándo debe pasar la siguiente inspección?", opciones: ["Dentro de 2 años.", "Dentro de 4 años.", "Al año siguiente."], correcta: 0, explicacion: "Un turismo pasa la primera ITV a los 4 años de su matriculación y después cada 2 años, hasta cumplir 10." }
    ] }
]);
